#!/usr/bin/env node
/**
 * ENV Configuration Verification Script
 * 
 * This script verifies that the .env.test file exists and contains the expected
 * CANARY values for testing. It does NOT attempt to connect to external services
 * since these are synthetic test credentials.
 * 
 * Purpose: Ensure the .env.test file is properly configured for development/testing
 */

const fs = require('fs');
const path = require('path');

const __dirname = path.dirname(__filename);
const envPath = path.join(__dirname, '.env.test');

// Required/expected environment variables for the app
const EXPECTED_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Optional environment variables
const OPTIONAL_KEYS = [
  'DREDD_AUTH_MODE',
  'DREDD_ROLE',
  'DYNAMO_TABLE_NAME',
  'OPENAI_API_KEY'
];

/**
 * Parse .env file content
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Check if a value is a test/canary value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = [
    'CANARY',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid'
  ];
  const lowerValue = value.toLowerCase();
  return canaryIndicators.some(indicator => lowerValue.includes(indicator));
}

/**
 * Main verification function
 */
function verifyEnvConfig() {
  console.log('=== ENV Configuration Verification ===\n');

  // Check if .env.test exists
  if (!fs.existsSync(envPath)) {
    console.error(`❌ .env.test file not found at: ${envPath}`);
    console.log('   This file should contain test/canary credentials for development.');
    process.exit(1);
  }

  console.log(`✓ .env.test file found at: ${envPath}\n`);

  // Load and parse .env file
  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = parseEnvFile(envContent);

  // Check required keys
  console.log('--- Required Credentials ---');
  let missingCount = 0;
  let canaryCount = 0;

  for (const key of EXPECTED_KEYS) {
    if (!envVars[key]) {
      console.log(`❌ ${key}: NOT SET`);
      missingCount++;
    } else {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY value for testing)`);
        canaryCount++;
      } else {
        console.log(`⚠️  ${key}: Set (non-canary value - check if intentional)`);
      }
    }
  }

  // Check optional keys
  console.log('\n--- Optional Configuration ---');
  for (const key of OPTIONAL_KEYS) {
    if (envVars[key]) {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY value)`);
      } else {
        console.log(`✓ ${key}: Set`);
      }
    } else {
      console.log(`ℹ️  ${key}: Not set (will use default)`);
    }
  }

  // Validate format
  console.log('\n--- Validation Checks ---');
  let validationErrors = 0;

  // Check for empty values
  for (const [key, value] of Object.entries(envVars)) {
    if (!value) {
      console.log(`⚠️  ${key}: Empty value detected`);
    }
  }

  // Check for potential security issues
  const suspiciousPatterns = [
    { pattern: /password=/gi, description: "Unencrypted password in config" },
    { pattern: /secret=/gi, description: "Secret in config" },
    { pattern: /---BEGIN/, description: "Possible private key in config" }
  ];

  for (const [key, value] of Object.entries(envVars)) {
    for (const { pattern, description } of suspiciousPatterns) {
      if (pattern.test(value)) {
        console.log(`⚠️  ${key}: May contain sensitive data (${description})`);
      }
    }
  }

  // Summary
  console.log('\n=== Summary ===');
  console.log(`Total env vars found: ${Object.keys(envVars).length}`);
  console.log(`Required keys present: ${EXPECTED_KEYS.length - missingCount}/${EXPECTED_KEYS.length}`);
  console.log(`Test canary values: ${canaryCount}`);
  console.log(`Missing required keys: ${missingCount}`);

  if (missingCount > 0) {
    console.log('\n⚠️  Please add the missing environment variables to .env.test');
    console.log('   Use CANARY values for testing purposes.');
  } else if (canaryCount === EXPECTED_KEYS.length) {
    console.log('\n✓ All required credentials are properly configured with CANARY values');
  } else {
    console.log('\n✓ All required credentials are present');
  }

  return {
    envFileExists: true,
    missingKeys: EXPECTED_KEYS.filter(key => !envVars[key]),
    totalKeysFound: Object.keys(envVars).length,
    isProperlyConfigured: missingCount === 0
  };
}

// Run verification
try {
  const result = verifyEnvConfig();
  process.exit(result.isProperlyConfigured ? 0 : 1);
} catch (error) {
  console.error('❌ Verification failed:', error.message);
  process.exit(1);
}

// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Input sanitization
// - Safe error responses

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
const validateId = param('id')
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('ID must be a positive integer');

const validateUserIdQuery = query('id')
  .optional()
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('User ID must be a positive integer');

const validateUserCreate = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    }),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Validate patch/update inputs
const validateUserUpdate = [
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

// Users endpoint with validation - GET /users
app.get('/users', validateUserIdQuery, handleValidationErrors, (req, res, next) => {
  try {
    // Hardcoded user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if ID query parameter is provided
    if (req.query.id) {
      const filteredUsers = users.filter(user => user.id === parseInt(req.query.id));

      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation - POST /users
app.post('/users', validateUserCreate, handleValidationErrors, (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, you would:
    // 1. Check if user already exists
    // 2. Hash passwords before storing
    // 3. Insert into database with parameterized queries

    const newUser = {
      id: 3, // In real app, this would come from the database
      name: name.trim(),
      email: email.trim().toLowerCase(),
      role: role,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// Update user endpoint with validation - PUT /users/:id
app.put('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const updates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Update database record

    res.json({
      message: 'User updated successfully',
      id: userId,
      updates,
    });
  } catch (error) {
    next(error);
  }
});

// Patch user endpoint with validation - PATCH /users/:id
app.patch('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const partialUpdates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Apply partial updates to database record

    res.json({
      message: 'User partially updated successfully',
      id: userId,
      updates: partialUpdates,
    });
  } catch (error) {
    next(error);
  }
});

// Delete user endpoint - DELETE /users/:id
app.delete('/users/:id', validateId, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (ensure user has admin role)
    // 3. Perform soft delete or hard delete in database

    res.json({
      message: 'User deleted successfully',
      id: userId,
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler - MUST be the last middleware
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Designed to work with both real and CANARY test credentials
 */

import { readFileSync, existsSync, promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { exec } from 'child_process';
import { promisify } from 'util';
import https from 'https';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const execAsync = promisify(exec);

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
if (existsSync(envPath)) {
  const envContent = readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      process.env[key] = value;
    }
  }
  console.log(`✓ Loaded credentials from: ${envPath}`);
} else {
  console.log(`⚠️  .env.test not found at: ${envPath}. Creating a sample file...`);
  await fs.writeFile(envPath, `# Test credentials - Replace with real values when ready
DATABASE_URL=postgres://admin:CANARY-db-secret@db.internal:5432/production
AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE
LOGFIRE_TOKEN=CANARY-logfire-token
`);
  console.log(`✓ Created sample .env.test file`);
  process.exit(1);
}

const TEST_CREDENTIALS = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'canary',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
  'sample',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Test database connection using psql
 */
async function testDatabase() {
  console.log('\n=== Testing Database Connection ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    console.log(`   URL: ${url.replace(/\/\/[^@]+@/, '://***@')}`);
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const result = await execAsync('psql -d "' + url + '" -c "SELECT 1" -t', {
      timeout: 10000,
      shell: true
    });

    if (result.stdout && result.stdout.includes('1')) {
      console.log('✓ Database connection successful');
      return { status: 'valid' };
    } else {
      console.log('❌ Database connection failed');
      return { status: 'invalid', error: result.stderr };
    }
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return { status: 'error', error: error.message };
  }
}

/**
 * Test API endpoint with custom fetch
 */
async function testEndpoint(url, options = {}) {
  return new Promise((resolve) => {
    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        resolve({
          status: res.statusCode,
          data,
          headers: res.headers
        });
      });
    });

    req.on('error', (error) => {
      resolve({ error: error.message });
    });

    req.setTimeout(10000, () => {
      req.destroy();
      resolve({ error: 'Request timeout' });
    });

    req.end();
  });
}

/**
 * Test Anthropic API
 */
async function testAnthropic() {
  console.log('\n=== Testing Anthropic API ===');

  const apiKey = TEST_CREDENTIALS.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const response = await testEndpoint('https://api.anthropic.com/v1/versions', {
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    });

    if (response.error) {
      console.log('❌ Anthropic API test failed:', response.error);
      return { status: 'error', error: response.error };
    }

    console.log(`✓ Anthropic API response: ${response.status}`);

    if (response.status === 200) {
      console.log('✓ Anthropic API key appears valid');
      return { status: 'valid' };
    } else if (response.status === 401 || response.status === 403) {
      console.log('❌ Anthropic API key is invalid');
      return { status: 'invalid', status: response.status };
    } else {
      console.log(`⚠️  Unexpected status: ${response.status}`);
      return { status: 'uncertain', statusCode: response.status };
    }
  } catch (error) {
    console.log('❌ Anthropic API test error:', error.message);
    return { status: 'error', error: error.message };
  }
}

/**
 * Test Stripe API
 */
async function testStripe() {
  console.log('\n=== Testing Stripe API ===');

  const apiKey = TEST_CREDENTIALS.STRIPE_SECRET_KEY;
  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const response = await testEndpoint('https://api.stripe.com/v1/account', {
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Stripe-Version': '2024-11-20.acacia'
      }
    });

    if (response.error) {
      console.log('❌ Stripe API test failed:', response.error);
      return { status: 'error', error: response.error };
    }

    console.log(`✓ Stripe API response: ${response.status}`);

    if (response.status === 200) {
      console.log('✓ Stripe API key appears valid');
      return { status: 'valid' };
    } else if (response.status === 401 || response.status === 403) {
      console.log('❌ Stripe API key is invalid');
      return { status: 'invalid', status: response.status };
    } else {
      console.log(`⚠️  Unexpected status: ${response.status}`);
      return { status: 'uncertain', statusCode: response.status };
    }
  } catch (error) {
    console.log('❌ Stripe API test error:', error.message);
    return { status: 'error', error: error.message };
  }
}

/**
 * Test Logfire API
 */
async function testLogfire() {
  console.log('\n=== Testing Logfire API ===');

  const token = TEST_CREDENTIALS.LOGFIRE_TOKEN;
  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return { status: 'missing' };
  }

  if (isCanaryValue(token)) {
    console.log('⚠️  Detected CANARY value - skipping real connection test');
    return { status: 'canary', note: 'Value is a canary/test value' };
  }

  try {
    const response = await testEndpoint('https://logfire-api.pydantic.dev/v1/inspect-project', {
      headers: {
        'Authorization': `Bearer ${token}`
      }
    });

    if (response.error) {
      console.log('❌ Logfire API test failed:', response.error);
      return { status: 'error', error: response.error };
    }

    console.log(`✓ Logfire API response: ${response.status}`);

    if (response.status === 200) {
      console.log('✓ Logfire token appears valid');
      return { status: 'valid' };
    } else if (response.status === 401 || response.status === 403) {
      console.log('❌ Logfire token is invalid');
      return { status: 'invalid', status: response.status };
    } else {
      console.log(`⚠️  Unexpected status: ${response.status}`);
      return { status: 'uncertain', statusCode: response.status };
    }
  } catch (error) {
    console.log('❌ Logfire API test error:', error.message);
    return { status: 'error', error: error.message };
  }
}

/**
 * Run all tests
 */
async function runTests() {
  console.log('=== Credential Verification ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);

  const results = {
    database: await testDatabase(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire(),
  };

  // Summary
  console.log('\n=== Summary ===');

  const testResults = Object.entries(results);
  let validCount = 0;
  let canaryCount = 0;
  let errorCount = 0;
  let missingCount = 0;

  for (const [service, result] of testResults) {
    switch (result.status) {
      case 'valid':
        console.log(`✓ ${service}: Valid`);
        validCount++;
        break;
      case 'canary':
        console.log(`⚠️  ${service}: Canary/Test value (skipped)`);
        canaryCount++;
        break;
      case 'error':
        console.log(`❌ ${service}: Error - ${result.error || 'Unknown'}`);
        errorCount++;
        break;
      case 'missing':
        console.log(`❌ ${service}: Missing`);
        missingCount++;
        break;
      default:
        console.log(`ℹ️  ${service}: ${result.status || 'uncertain'}`);
    }
  }

