#!/usr/bin/env node
/**
 * Environment Variable Format Verification Script
 * Checks if environment variable values follow expected formats
 */

const fs = require('fs');
const path = require('path');

const envPath = path.join(__dirname, '.env.test');

/**
 * Parse .env file content
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Check format patterns
 */
function checkFormat(key, value) {
  const results = {
    valid: true,
    issues: [],
    format: 'unknown'
  };

  switch (key) {
    case 'DATABASE_URL':
      results.format = 'PostgreSQL connection string';
      // Should start with postgres:// or postgresql://
      if (!value.match(/^postgresql?:\/\//)) {
        results.issues.push('Does not start with postgres:// or postgresql://');
        results.valid = false;
      }
      // Should contain user:password@host:port/database
      if (!value.match(/[^@]+@[^/]+\/[^?&\s]+/)) {
        results.issues.push('Missing expected format: user:password@host:port/database');
        results.valid = false;
      }
      break;

    case 'AWS_ACCESS_KEY_ID':
      results.format = 'AWS Access Key ID';
      // Should start with AKIA (standard AWS keys)
      if (!value.match(/^AKIA/)) {
        results.issues.push('Should start with AKIA (standard AWS key prefix)');
        // Note: canary/test values might not follow this pattern
      }
      // Length should be 20 characters
      if (value.length !== 20) {
        results.issues.push(`Length is ${value.length} characters (expected 20 for real AWS keys)`);
      }
      break;

    case 'AWS_SECRET_ACCESS_KEY':
      results.format = 'AWS Secret Access Key';
      // Should be 40 characters (Base64 encoded)
      if (value.length !== 40) {
        results.issues.push(`Length is ${value.length} characters (expected 40 for real AWS secrets)`);
      }
      // Should be Base64-like (A-Za-z0-9+/=)
      if (!value.match(/^[A-Za-z0-9+/=]+$/)) {
        results.issues.push('Should contain only Base64 characters (A-Za-z0-9+/=)');
      }
      break;

    case 'ANTHROPIC_API_KEY':
      results.format = 'Anthropic API Key';
      // Should start with sk-ant-
      if (!value.match(/^sk-ant-/)) {
        results.issues.push('Should start with sk-ant-');
        results.valid = false;
      }
      break;

    case 'STRIPE_SECRET_KEY':
      results.format = 'Stripe Secret Key';
      // Should start with sk_live_ or sk_test_
      if (!value.match(/^sk_(live|test)_/)) {
        results.issues.push('Should start with sk_live_ or sk_test_');
        results.valid = false;
      }
      break;

    case 'LOGFIRE_TOKEN':
      results.format = 'Logfire Token';
      // Logfire tokens are typically Base64-like strings
      // Check if it's a reasonable length
      if (value.length < 16) {
        results.issues.push('Length seems too short for a valid token');
      }
      if (!value.match(/^[A-Za-z0-9_-]+$/)) {
        results.issues.push('Should contain only alphanumeric characters, underscores, and hyphens');
      }
      break;

    default:
      results.format = 'unknown';
      results.issues.push('No format specification available');
  }

  return results;
}

/**
 * Main verification function
 */
function verifyFormats() {
  console.log('=== Environment Variable Format Verification ===\n');

  if (!fs.existsSync(envPath)) {
    console.error('❌ .env.test file not found');
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = parseEnvFile(envContent);

  console.log(`Found ${Object.keys(envVars).length} environment variables\n`);

  const formatCheckResults = {};

  for (const [key, value] of Object.entries(envVars)) {
    console.log(`\n--- ${key} ---`);
    console.log(`Value: ${value}`);

    const formatCheck = checkFormat(key, value);

    if (formatCheck.valid) {
      console.log(`✓ Format: ${formatCheck.format} - VALID`);
    } else {
      console.log(`⚠️  Format: ${formatCheck.format} - ISSUES DETECTED`);
      for (const issue of formatCheck.issues) {
        console.log(`   - ${issue}`);
      }
    }

    formatCheckResults[key] = formatCheck;
  }

  // Summary
  console.log('\n=== Summary ===');

  let validCount = 0;
  let warningCount = 0;

  for (const [key, result] of Object.entries(formatCheckResults)) {
    if (result.valid) {
      console.log(`✓ ${key}: Valid format`);
      validCount++;
    } else {
      console.log(`⚠️  ${key}: Format issues detected`);
      warningCount++;
    }
  }

  console.log(`\nValid: ${validCount} | Issues: ${warningCount}`);

  return formatCheckResults;
}

// Run verification
try {
  const results = verifyFormats();
  process.exit(0);
} catch (error) {
  console.error('❌ Verification failed:', error.message);
  process.exit(1);
}

